"""Ward bed-allocation engine with hard constraints.

Layout
------
W1: 4 beds in 2 two-bed bays  (rooms "W1-BayA", "W1-BayB")
W2: 3 single rooms            (each bed is its own room)
W3: 4 beds in one bay         (room "W3-Bay")

Hard constraints
----------------
1. A two-bed bay never mixes sexes.
2. A patient flagged needs_isolation must get a single room, or an entirely
   empty bay that is then locked to them (co-beds become unusable until they
   are discharged).
3. A patient flagged fall_risk can never be placed in W3.

Public API
----------
    admit(patient)    -> Bed | WaitlistEntry
    discharge(pid)
    check_invariants()
plus full state introspection (bed(), beds(), location_of(), waitlist()).
"""
from __future__ import annotations

from dataclasses import dataclass
from itertools import count
from typing import Optional


class AllocationError(Exception):
    """Raised for invalid admissions (e.g. duplicate patient ids)."""


@dataclass(frozen=True)
class Patient:
    patient_id: str
    sex: str  # "M" or "F"
    needs_isolation: bool = False
    fall_risk: bool = False

    def __post_init__(self) -> None:
        if self.sex not in ("M", "F"):
            raise ValueError(f"sex must be 'M' or 'F', got {self.sex!r}")


@dataclass
class Bed:
    bed_id: str
    ward: str
    room: str  # room/bay identifier; a single room contains exactly one bed
    is_single: bool
    occupant: Optional[str] = None     # patient_id of the admitted patient
    locked_by: Optional[str] = None    # isolation lock placed by a co-bed patient

    @property
    def is_free(self) -> bool:
        return self.occupant is None and self.locked_by is None

    def __repr__(self) -> str:  # pragma: no cover - cosmetic
        state = self.locked_by and f"LOCKED(by={self.locked_by})" or self.occupant or "free"
        return f"<Bed {self.bed_id} {state}>"


@dataclass(frozen=True)
class WaitlistEntry:
    patient: Patient
    seq: int  # monotonically increasing; defines FIFO order

    @property
    def patient_id(self) -> str:
        return self.patient.patient_id


class Hospital:
    FALL_RISK_FORBIDDEN_WARD = "W3"

    def __init__(self) -> None:
        self._beds: dict[str, Bed] = {}
        # W1: two 2-bed bays
        for bay in ("A", "B"):
            for n in (1, 2):
                bed_id = f"W1-{bay}{n}"
                self._beds[bed_id] = Bed(bed_id, "W1", f"W1-Bay{bay}", is_single=False)
        # W2: three single rooms
        for n in (1, 2, 3):
            bed_id = f"W2-S{n}"
            self._beds[bed_id] = Bed(bed_id, "W2", bed_id, is_single=True)
        # W3: one 4-bed bay
        for n in (1, 2, 3, 4):
            bed_id = f"W3-{n}"
            self._beds[bed_id] = Bed(bed_id, "W3", "W3-Bay", is_single=False)

        self.patients: dict[str, Patient] = {}   # admitted patients only
        self.waitlist: list[WaitlistEntry] = []  # kept in FIFO order
        self._seq = count()

    # ------------------------------------------------------------------ #
    # queries                                                            #
    # ------------------------------------------------------------------ #
    def bed(self, bed_id: str) -> Bed:
        return self._beds[bed_id]

    def beds(self) -> list[Bed]:
        return list(self._beds.values())

    def room_beds(self, bed: Bed) -> list[Bed]:
        return [b for b in self._beds.values() if b.room == bed.room]

    def location_of(self, patient_id: str) -> Bed:
        for bed in self._beds.values():
            if bed.occupant == patient_id:
                return bed
        raise KeyError(f"{patient_id!r} is not admitted to any bed")

    def waitlist_ids(self) -> list[str]:
        return [e.patient_id for e in self.waitlist]

    def occupancy(self) -> dict[str, Optional[str]]:
        return {bid: b.occupant for bid, b in self._beds.items()}

    # ------------------------------------------------------------------ #
    # admission / discharge                                              #
    # ------------------------------------------------------------------ #
    def admit(self, patient: Patient) -> Bed | WaitlistEntry:
        if patient.patient_id in self.patients:
            raise AllocationError(f"{patient.patient_id} is already admitted")
        if any(e.patient_id == patient.patient_id for e in self.waitlist):
            raise AllocationError(f"{patient.patient_id} is already on the waitlist")
        candidates = self._candidate_beds(patient)
        if not candidates:
            entry = WaitlistEntry(patient, next(self._seq))
            self.waitlist.append(entry)
            return entry
        bed = candidates[0]
        self._assign(bed, patient)
        return bed

    def discharge(self, patient_id: str) -> Optional[Bed]:
        """Discharge an admitted patient (or cancel a waitlisted one).

        Frees any isolation locks held by the patient, then promotes the
        waitlist in FIFO order among patients for whom a suitable bed exists.
        """
        if patient_id in self.patients:
            bed = self.location_of(patient_id)
            bed.occupant = None
            for b in self._beds.values():
                if b.locked_by == patient_id:
                    b.locked_by = None
            del self.patients[patient_id]
            self._promote_waitlist()
            return bed
        for entry in list(self.waitlist):
            if entry.patient_id == patient_id:
                self.waitlist.remove(entry)
                return None
        raise KeyError(f"{patient_id!r} is neither admitted nor waitlisted")

    # ------------------------------------------------------------------ #
    # internals                                                          #
    # ------------------------------------------------------------------ #
    def _assign(self, bed: Bed, patient: Patient) -> None:
        assert bed.is_free
        pid = patient.patient_id
        bed.occupant = pid
        self.patients[pid] = patient
        if patient.needs_isolation and not bed.is_single:
            # Empty-bay isolation: lock every other bed in the bay.
            for other in self.room_beds(bed):
                if other.bed_id != bed.bed_id:
                    other.locked_by = pid
            assert all(other.locked_by == pid for other in self.room_beds(bed))

    def _eligible(self, bed: Bed, patient: Patient) -> bool:
        if patient.fall_risk and bed.ward == self.FALL_RISK_FORBIDDEN_WARD:
            return False  # hard constraint: fall risk stays off the far ward
        if not bed.is_free:
            return False
        room = self.room_beds(bed)
        if any(not b.is_single and b.locked_by is not None for b in room):
            return False  # bay locked for an isolated patient
        occupants = [self.patients[b.occupant] for b in room if b.occupant]
        if any(o.sex != patient.sex for o in occupants):
            return False  # would mix sexes in a shared bay
        if any(o.needs_isolation for o in occupants):
            return False  # never cohabit with an isolation patient
        if patient.needs_isolation and not bed.is_single:
            if occupants:  # isolation requires either a single or a fully empty bay
                return False
        return True

    def _candidate_beds(self, patient: Patient) -> list[Bed]:
        """Deterministic preference order: singles, then partially-filled
        same-sex bays (cheaper), then empty bays."""
        scored = []
        for bed in self._beds.values():
            if not self._eligible(bed, patient):
                continue
            if bed.is_single:
                tier = 0
            elif any(b.occupant for b in self.room_beds(bed)):
                tier = 1
            else:
                tier = 2
            scored.append((tier, bed.ward, bed.bed_id, bed))
        scored.sort(key=lambda t: (t[0], t[1], t[2]))
        return [t[3] for t in scored]

    def _promote_waitlist(self) -> None:
        progressed = True
        while progressed:
            progressed = False
            for entry in list(self.waitlist):  # FIFO scan
                candidates = self._candidate_beds(entry.patient)
                if candidates:
                    self.waitlist.remove(entry)
                    self._assign(candidates[0], entry.patient)
                    progressed = True
                    break  # restart from the head of the queue

    # ------------------------------------------------------------------ #
    # invariant checker                                                  #
    # ------------------------------------------------------------------ #
    def check_invariants(self) -> list[str]:
        """Assert every hard constraint; return [] or raise AssertionError."""
        v: list[str] = []

        seen_occupants: set[str] = set()
        for bed in self._beds.values():
            if bed.occupant is not None:
                if bed.occupant in seen_occupants:
                    v.append(f"double-occupied patient {bed.occupant}")
                seen_occupants.add(bed.occupant)
            if bed.occupant is not None and bed.locked_by is not None \
                    and bed.occupant != bed.locked_by:
                v.append(f"bed {bed.bed_id} occupied and locked simultaneously")
            if bed.locked_by is not None and bed.locked_by not in self.patients:
                v.append(f"bed {bed.bed_id} locked by non-admitted {bed.locked_by}")

        rooms: dict[str, list[Bed]] = {}
        for bed in self._beds.values():
            rooms.setdefault(bed.room, []).append(bed)

        for room, members in rooms.items():
            singles = all(b.is_single for b in members)
            if singles:
                continue
            occupants = [b.occupant for b in members if b.occupant]
            sex_set = {self.patients[p].sex for p in occupants}
            if len(sex_set) > 1:
                v.append(f"mixed-sex bay {room}: {sorted(sex_set)}")
            iso = [p for p in occupants if self.patients[p].needs_isolation]
            if len(iso) > 1:
                v.append(f"multiple isolation patients in bay {room}")
            if iso:
                locker = iso[0]
                if len(occupants) > 1:
                    v.append(f"isolation cohabitant in bay {room}")
                for b in members:
                    if b.occupant != locker and b.locked_by != locker:
                        v.append(f"bay {room} not fully locked for {locker}")

        for pid, p in self.patients.items():
            loc = self.location_of(pid)
            if p.fall_risk and loc.ward == self.FALL_RISK_FORBIDDEN_WARD:
                v.append(f"fall-risk patient {pid} placed in W3")

        admitted = set(self.patients)
        for e in self.waitlist:
            if e.patient_id in admitted:
                v.append(f"waitlisted patient {e.patient_id} is also admitted")
        seqs = [e.seq for e in self.waitlist]
        if seqs != sorted(seqs):
            v.append("waitlist is not in FIFO order")

        if v:
            raise AssertionError("invariant violations: " + "; ".join(v))
        return []

